<template>
  <PageShell :title="tabTitle" description="用受控的数据源、组件和布局配置报表、业务页面与可视化大屏。">
    <template #actions>
      <button class="button button-ghost" :disabled="loading" @click="load">↻ 刷新配置</button>
      <button v-if="canEdit && tab === 'reports'" class="button button-primary" @click="openReportCreate">+ 新建报表</button>
      <button v-if="canEdit && tab === 'data-sources'" class="button button-primary" @click="openSourceCreate">+ 新建数据源</button>
      <button v-if="canEdit && tab === 'low-code'" class="button button-primary" @click="openPageCreate">+ 新建页面</button>
      <button v-if="canEdit && tab === 'big-screen'" class="button button-primary" @click="openDashboardCreate">+ 新建大屏</button>
    </template>
    <div class="subnav"><button v-for="item in tabs" :key="item.key" :class="['subnav-item', { active: tab === item.key }]" @click="switchTab(item.key)">{{ item.label }}</button></div>
    <div v-if="notice" :class="['notice-bar', `notice-${notice.type}`]" role="status"><span>{{ notice.type === 'error' ? '!' : '✓' }}</span>{{ notice.message }}</div>

    <div v-if="tab === 'reports'" class="design-grid">
      <div v-for="report in reports" :key="report.id" class="design-card"><div class="design-card__icon chart-icon">◒</div><div class="design-card__body"><span class="eyebrow">{{ report.chart_type || 'TABLE' }}</span><h3>{{ report.report_name }}</h3><p>{{ report.report_code }} · {{ sourceName(report.source_table) }}</p></div><div class="design-card__foot"><span :class="['status-pill', report.status === 'PUBLISHED' ? 'status-released' : 'status-planned']">{{ report.status === 'PUBLISHED' ? '已发布' : '草稿' }}</span><span class="design-updated">{{ formatDate(report.updated_at) }}</span></div><div class="design-card__actions"><button class="text-button" @click="previewReport(report)">预览数据</button><button v-if="canEdit" class="text-button" @click="openReportEdit(report)">编辑</button><button v-if="canEdit && report.status !== 'PUBLISHED'" class="text-button" @click="publishReport(report)">发布</button></div></div>
      <div v-if="!reports.length" class="empty-operation">暂无报表配置，请创建第一张报表</div>
    </div>

    <div v-else-if="tab === 'data-sources'" class="source-layout"><div class="panel source-guide"><div class="panel-heading"><div><h3>数据源目录</h3><p>报表和大屏只能引用已启用的数据源</p></div></div><div class="source-flow"><span>连接配置</span><i>→</i><span>字段元数据</span><i>→</i><span>报表 / 大屏</span></div><div class="callout">建议把连接信息、允许查询的表/字段和刷新策略集中维护；业务设计人员只选择数据源，不直接编写任意 SQL。</div><div class="source-stat"><b>{{ dataSources.length }}</b><span>已注册数据源</span></div><div class="source-stat"><b>{{ enabledSources }}</b><span>当前启用</span></div></div><div class="panel"><div class="panel-heading"><div><h3>数据源配置</h3><p>内置业务表和租户自定义数据源统一管理</p></div></div><DataTable :columns="sourceColumns" :rows="dataSources" :loading="loading" :show-toolbar="true" :enable-export="true" :pagination="true" table-title="数据源" table-hint="配置保存后才能被报表与大屏引用" export-name="polaris-data-sources"><template #cell-enabled="{ row }"><span :class="['status-pill', row.enabled ? 'status-released' : 'status-planned']">{{ row.enabled ? '启用' : '停用' }}</span></template><template #actions="{ row }"><button v-if="canEdit" class="table-action" @click="openSourceEdit(row)">编辑</button><button v-if="canEdit" class="table-action" @click="toggleSource(row)">{{ row.enabled ? '停用' : '启用' }}</button></template></DataTable></div></div>

    <div v-else-if="tab === 'low-code'" class="builder-layout builder-layout--rich"><aside class="builder-palette"><div class="builder-side-heading"><div><h3>页面与组件</h3><p>拖入画布或点击添加</p></div><button v-if="canEdit" class="mini-add" @click="openPageCreate">+</button></div><button v-for="page in lowCodePages" :key="page.id" class="palette-item" :class="{ active: selectedPage?.id === page.id }" @click="selectPage(page)"><span>□</span>{{ page.page_name }}<small>{{ page.status === 'PUBLISHED' ? '已发布' : '草稿' }}</small></button><div class="palette-divider"></div><button v-for="component in componentCatalog" :key="component.type" class="component-palette-item" draggable="true" @dragstart="dragComponent(component)" @click="addComponent(component)"><span>{{ component.icon }}</span><b>{{ component.label }}</b><small>{{ component.hint }}</small></button></aside><div class="builder-canvas builder-canvas--grid"><div class="canvas-toolbar"><span>{{ selectedPage?.page_name || '未选择页面' }} <em v-if="selectedPage">· {{ pageSchema.layout }} 列布局</em></span><span v-if="selectedPage"><button @click="showPagePreview = true">预览</button><button v-if="canEdit" class="button button-primary" @click="savePage">保存</button><button v-if="canEdit" class="button button-primary" :disabled="selectedPage.status === 'PUBLISHED'" @click="publishPage">发布</button></span></div><div v-if="selectedPage" class="form-canvas form-canvas--builder" @dragover.prevent @drop="dropComponent"><div class="canvas-title"><span class="drag-handle">▣</span><div><h2>{{ pageForm.pageName }}</h2><p>{{ pageForm.pageType }} · 从左侧拖入组件，点击组件后在右侧编辑属性</p></div></div><div class="component-grid" :style="{ gridTemplateColumns: `repeat(${pageSchema.layout}, minmax(0, 1fr))` }"><div v-for="(component, index) in pageComponents" :key="component.id" class="canvas-component" :class="{ selected: selectedComponentId === component.id }" draggable="true" @dragstart.stop="dragExisting(index)" @dragover.prevent @drop.stop="dropExisting(index)" @click="selectedComponentId = component.id"><div class="canvas-component__head"><span class="component-grip">⠿</span><b>{{ component.props?.label || component.type }}</b><button v-if="canEdit" @click.stop="removeComponent(index)">×</button></div><div class="canvas-component__body"><input v-if="component.type === 'input' || component.type === 'number' || component.type === 'date'" disabled :placeholder="component.props?.placeholder || '请输入'" :type="component.type === 'number' ? 'number' : 'text'" /><textarea v-else-if="component.type === 'textarea'" disabled placeholder="多行文本区域"></textarea><select v-else-if="component.type === 'select'" disabled><option>{{ component.props?.options || '请选择' }}</option></select><div v-else-if="component.type === 'table'" class="component-preview-table"><i v-for="n in 3" :key="n"></i></div><div v-else-if="component.type === 'chart'" class="component-preview-chart"><i v-for="n in 6" :key="n" :style="{ height: `${20 + n * 10}%` }"></i></div><div v-else-if="component.type === 'stat'" class="component-preview-stat"><strong>128</strong><small>{{ component.props?.label || '指标卡' }}</small></div><div v-else class="component-preview-divider"></div></div></div><div v-if="!pageComponents.length" class="drop-empty">把左侧组件拖到这里开始搭建页面</div></div></div><div class="builder-statusbar"><span>组件 {{ pageComponents.length }} 个</span><span>布局 schema 自动持久化</span></div></div><aside class="builder-properties"><h3>页面属性</h3><label>页面编码<input v-model.trim="pageForm.pageCode" :disabled="Boolean(editingPage)" /></label><label>页面名称<input v-model.trim="pageForm.pageName" /></label><label>页面类型<select v-model="pageForm.pageType"><option value="FORM">表单</option><option value="QUERY">查询页</option><option value="DASHBOARD">工作台</option></select></label><label>布局列数<select v-model.number="pageSchema.layout"><option :value="1">单列</option><option :value="2">双列</option><option :value="3">三列</option></select></label><label>提交接口<input v-model.trim="pageForm.submitApi" placeholder="/api/warehouse/transactions" /></label><div v-if="selectedComponent" class="property-section"><h4>组件属性</h4><label>组件标题<input v-model.trim="selectedComponent.props.label" /></label><label>占位提示<input v-model.trim="selectedComponent.props.placeholder" /></label><label>字段编码<input v-model.trim="selectedComponent.props.name" /></label><label v-if="selectedComponent.type === 'select'">选项文本<input v-model.trim="selectedComponent.props.options" /></label></div><div class="property-tip">企业级低代码页面建议：先选页面布局，再从组件面板拖拽，组件属性通过 schema 保存；发布前可预览，发布后由权限和接口策略控制。</div></aside></div>

    <div v-else-if="tab === 'big-screen'" class="screen-builder"><aside class="screen-config-panel"><div class="builder-side-heading"><div><h3>大屏目录</h3><p>配置、预览、发布分离</p></div><button v-if="canEdit" class="mini-add" @click="openDashboardCreate">+</button></div><button v-for="dashboard in dashboards" :key="dashboard.id" class="palette-item" :class="{ active: selectedDashboard?.id === dashboard.id }" @click="selectDashboard(dashboard)"><span>▣</span>{{ dashboard.dashboard_name }}<small>{{ dashboard.status === 'PUBLISHED' ? '已发布' : '草稿' }}</small></button><div class="palette-divider"></div><b class="screen-config-label">大屏属性</b><label>大屏编码<input v-model.trim="dashboardForm.dashboardCode" :disabled="Boolean(editingDashboard)" /></label><label>大屏名称<input v-model.trim="dashboardForm.dashboardName" /></label><label>主题<select v-model="dashboardForm.theme"><option value="dark-blue">深海蓝</option><option value="midnight">午夜黑</option><option value="factory">工厂青</option></select></label><label>网格列数<select v-model.number="dashboardSchema.columns"><option :value="2">两列</option><option :value="3">三列</option><option :value="4">四列</option></select></label><div v-if="selectedScreenWidget" class="property-section screen-widget-properties"><h4>组件数据绑定</h4><label>组件标题<input v-model.trim="selectedScreenWidget.title" /></label><label>数据源<select v-model="selectedScreenWidget.dataSource"><option v-for="source in dataSources" :key="source.source_code" :value="source.source_code">{{ source.source_name }}</option></select></label><label>刷新间隔（秒）<input v-model.number="selectedScreenWidget.refreshSeconds" type="number" min="5" /></label></div><button v-if="canEdit && selectedDashboard" class="button button-primary full-button" @click="saveDashboard">保存大屏配置</button><button v-if="canEdit && selectedDashboard" class="button button-ghost full-button" :disabled="selectedDashboard.status === 'PUBLISHED'" @click="publishDashboard">发布大屏</button></aside><div class="screen-editor"><div class="screen-editor-toolbar"><span>组件编排 · 拖拽调整顺序</span><span><button v-for="widget in screenCatalog" :key="widget.type" draggable="true" class="screen-tool" @dragstart="dragScreenWidget(widget)" @click="addScreenWidget(widget)">{{ widget.icon }} {{ widget.label }}</button></span></div><div class="big-screen-preview big-screen-preview--editable" @dragover.prevent @drop="dropScreenWidget"><div class="big-screen-header"><div><span>POLARIS · FACTORY COMMAND CENTER</span><h2>{{ dashboardForm.dashboardName || '工厂运营驾驶舱' }}</h2></div><span>配置预览 · {{ screenWidgets.length }} 个组件</span></div><div class="screen-grid screen-grid--config" :style="{ gridTemplateColumns: `repeat(${dashboardSchema.columns}, minmax(0, 1fr))` }"><div v-for="(widget, index) in screenWidgets" :key="widget.id" :class="['screen-panel', 'screen-widget', { selected: selectedWidgetId === widget.id }]" draggable="true" @dragstart.stop="dragExistingWidget(index)" @dragover.prevent @drop.stop="dropExistingWidget(index)" @click="selectedWidgetId = widget.id"><div class="screen-widget__head"><h3>{{ widget.title }} <small>{{ widget.type }}</small></h3><button @click.stop="removeScreenWidget(index)">×</button></div><div v-if="widget.type === 'kpi'" class="widget-kpi"><strong>{{ widget.value || '1,280' }}</strong><span>{{ widget.subtitle || '当前累计完成' }}</span></div><div v-else-if="widget.type === 'trend'" class="screen-line"><i v-for="n in 7" :key="n" :style="{ height: `${20 + n * 9}%` }"></i></div><div v-else-if="widget.type === 'donut'" class="screen-donut"><strong>68%</strong></div><div v-else class="widget-alert-list"><p v-for="n in 3" :key="n"><i></i>{{ widget.type === 'table' ? `工单 WO-00${n}` : `库存预警 ${n}` }}<small>{{ n * 12 }} 件</small></p></div></div><div v-if="!screenWidgets.length" class="drop-empty">从上方拖入组件，开始配置大屏</div></div></div></div></div>

    <AppModal v-model="showReportModal" :title="editingReport ? '编辑报表' : '新建报表'" subtitle="报表只能选择已启用的数据源，配置 JSON 用于维度、指标和筛选条件" :loading="saving" confirm-text="保存报表" @confirm="saveReport"><div class="release-form-grid"><label>报表编码<input v-model.trim="reportForm.reportCode" :disabled="Boolean(editingReport)" /></label><label>报表名称<input v-model.trim="reportForm.reportName" /></label><label>数据源<select v-model="reportForm.sourceTable"><option v-for="source in dataSources.filter(item => item.enabled)" :key="source.source_code" :value="source.source_code">{{ source.source_name }}（{{ source.source_code }}）</option></select></label><label>图表类型<select v-model="reportForm.chartType"><option value="TABLE">明细表</option><option value="PIE">分布图</option><option value="BAR">柱状图</option><option value="LINE">趋势图</option></select></label></div><label>配置 JSON<textarea v-model="reportForm.configJson" rows="6" spellcheck="false"></textarea></label></AppModal>
    <AppModal v-model="showSourceModal" :title="editingSource ? '编辑数据源' : '新建数据源'" subtitle="连接信息仅用于受控查询，建议只保存白名单和元数据" :loading="saving" confirm-text="保存数据源" @confirm="saveSource"><div class="release-form-grid"><label>数据源编码<input v-model.trim="sourceForm.sourceCode" :disabled="Boolean(editingSource)" /></label><label>数据源名称<input v-model.trim="sourceForm.sourceName" /></label><label>类型<select v-model="sourceForm.sourceType"><option value="TABLE">业务表</option><option value="SQL">受控 SQL</option><option value="API">接口</option></select></label><label>状态<select v-model.number="sourceForm.status"><option :value="1">启用</option><option :value="0">停用</option></select></label></div><label>连接 / 查询配置 JSON<textarea v-model="sourceForm.configJson" rows="4" spellcheck="false"></textarea></label><label>字段元数据 JSON<textarea v-model="sourceForm.schemaJson" rows="4" spellcheck="false"></textarea></label></AppModal>
    <AppModal v-model="showPageModal" :title="editingPage ? '编辑页面' : '新建页面'" subtitle="页面创建后，在画布中拖入系统组件并保存 schema" :loading="saving" confirm-text="保存页面" @confirm="savePage"><label>页面编码<input v-model.trim="pageForm.pageCode" :disabled="Boolean(editingPage)" /></label><label>页面名称<input v-model.trim="pageForm.pageName" /></label><label>页面类型<select v-model="pageForm.pageType"><option value="FORM">表单</option><option value="QUERY">查询页</option><option value="DASHBOARD">工作台</option></select></label></AppModal>
    <AppModal v-model="showDashboardModal" :title="editingDashboard ? '编辑大屏' : '新建大屏'" subtitle="创建后可在画布中拖入指标、趋势、环形图和预警组件" :loading="saving" confirm-text="保存大屏" @confirm="saveDashboard"><label>大屏编码<input v-model.trim="dashboardForm.dashboardCode" :disabled="Boolean(editingDashboard)" /></label><label>大屏名称<input v-model.trim="dashboardForm.dashboardName" /></label></AppModal>
    <AppModal v-model="showPreviewModal" title="报表实时预览" :subtitle="`${previewData?.report_name || ''} · 返回 ${previewRows.length} 行`" hide-footer><div class="table-wrap"><table class="data-table"><thead><tr><th v-for="column in previewColumns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="row in previewRows" :key="JSON.stringify(row)"><td v-for="column in previewColumns" :key="column">{{ row[column] }}</td></tr><tr v-if="!previewRows.length"><td :colspan="previewColumns.length || 1" class="empty-state">暂无实时数据</td></tr></tbody></table></div></AppModal>
    <AppModal v-model="showPagePreview" :title="`${pageForm.pageName || '页面'} · 预览`" subtitle="当前预览直接来自已配置组件 schema" hide-footer><div class="preview-component-list"><div v-for="component in pageComponents" :key="component.id" class="preview-component"><b>{{ component.props?.label || component.type }}</b><input v-if="['input','number','date'].includes(component.type)" :type="component.type === 'number' ? 'number' : 'text'" :placeholder="component.props?.placeholder || ''" /><select v-else-if="component.type === 'select'"><option>{{ component.props?.options || '请选择' }}</option></select><textarea v-else-if="component.type === 'textarea'"></textarea><div v-else class="preview-component-box">{{ component.type === 'chart' ? '图表组件' : component.type === 'table' ? '数据表格组件' : component.type === 'stat' ? '指标卡组件' : '分隔线' }}</div></div></div></AppModal>
  </PageShell>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageShell from '../components/PageShell.vue'
import DataTable from '../components/DataTable.vue'
import AppModal from '../components/AppModal.vue'
import { request } from '../api'

const route = useRoute(); const router = useRouter(); const tab = ref(route.params.tab || 'reports'); const loading = ref(false); const saving = ref(false); const notice = ref(null); const canEdit = computed(() => { try { return ['admin', 'planner'].includes(JSON.parse(localStorage.getItem('polaris-user') || '{}').roleCode) } catch { return false } })
const tabs = [{ key: 'reports', label: '快速报表' }, { key: 'data-sources', label: '数据源' }, { key: 'low-code', label: '低代码页面' }, { key: 'big-screen', label: '大屏展示' }]; const tabTitle = computed(() => tabs.find(item => item.key === tab.value)?.label || '设计中心')
const reports = ref([]); const dataSources = ref([]); const lowCodePages = ref([]); const dashboards = ref([]); const dashboardOverview = ref({}); const selectedPageId = ref(null); const selectedDashboardId = ref(null); const selectedWidgetId = ref(null); const pageForm = ref({}); const dashboardForm = ref({}); const pageSchema = ref({ layout: 2, components: [], submitApi: '' }); const dashboardSchema = ref({ columns: 3, widgets: [] }); const selectedComponentId = ref(null); const dragState = ref(null); const dragWidgetState = ref(null)
const showReportModal = ref(false); const showSourceModal = ref(false); const showPageModal = ref(false); const showDashboardModal = ref(false); const showPreviewModal = ref(false); const showPagePreview = ref(false); const editingReport = ref(null); const editingSource = ref(null); const editingPage = ref(null); const editingDashboard = ref(null); const previewData = ref(null)
const reportForm = ref({ reportCode: '', reportName: '', sourceTable: '', chartType: 'TABLE', configJson: '{\n  "dimension": "status",\n  "metric": "count(*)"\n}' }); const sourceForm = ref({ sourceCode: '', sourceName: '', sourceType: 'TABLE', configJson: '{}', schemaJson: '{\n  "columns": []\n}', status: 1 })
const componentCatalog = [{ type: 'input', label: '单行输入', icon: '▭', hint: '文本 / 编码' }, { type: 'number', label: '数字输入', icon: '#', hint: '数量 / 金额' }, { type: 'select', label: '下拉选择', icon: '⌄', hint: '字典 / 选项' }, { type: 'date', label: '日期选择', icon: '◷', hint: '日期 / 时间' }, { type: 'textarea', label: '多行文本', icon: '≡', hint: '备注 / 说明' }, { type: 'table', label: '数据表格', icon: '▦', hint: '查询结果' }, { type: 'chart', label: '趋势图表', icon: '◒', hint: '指标趋势' }, { type: 'stat', label: '指标卡', icon: '∑', hint: '关键指标' }, { type: 'divider', label: '分隔线', icon: '—', hint: '布局辅助' }]
const screenCatalog = [{ type: 'kpi', label: '指标卡', icon: '▣' }, { type: 'trend', label: '趋势图', icon: '⌁' }, { type: 'donut', label: '环形图', icon: '◉' }, { type: 'alerts', label: '预警列表', icon: '!' }, { type: 'table', label: '明细表', icon: '▦' }]
const selectedPage = computed(() => lowCodePages.value.find(item => item.id === selectedPageId.value)); const pageComponents = computed(() => pageSchema.value.components || []); const selectedComponent = computed(() => pageComponents.value.find(item => item.id === selectedComponentId.value)); const selectedDashboard = computed(() => dashboards.value.find(item => item.id === selectedDashboardId.value)); const screenWidgets = computed(() => dashboardSchema.value.widgets || []); const selectedScreenWidget = computed(() => screenWidgets.value.find(item => item.id === selectedWidgetId.value)); const enabledSources = computed(() => dataSources.value.filter(item => item.enabled).length); const previewRows = computed(() => previewData.value?.rows || []); const previewColumns = computed(() => previewRows.value.length ? Object.keys(previewRows.value[0]) : [])
const sourceColumns = [{ key: 'source_code', label: '编码' }, { key: 'source_name', label: '名称' }, { key: 'source_type', label: '类型' }, { key: 'enabled', label: '状态' }, { key: 'updated_at', label: '更新时间', format: formatDate }]

function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }; function sourceName(code) { return dataSources.value.find(item => item.source_code === code)?.source_name || code || '-' }; function showNotice(message, type = 'success') { notice.value = { message, type }; window.clearTimeout(showNotice.timer); showNotice.timer = window.setTimeout(() => notice.value = null, 3600) }; function switchTab(value) { tab.value = value; router.push(`/design/${value}`); load() }
function parseJson(value, fallback) { try { return JSON.parse(value || '') } catch { return fallback } }; function defaultComponent(component) { const labels = { input: '文本字段', number: '数量字段', select: '状态选择', date: '业务日期', textarea: '备注说明', table: '查询结果', chart: '趋势图', stat: '关键指标', divider: '' }; return { id: `${component.type}-${Date.now()}-${Math.random().toString(16).slice(2)}`, type: component.type, props: { label: labels[component.type] || component.label, name: component.type, placeholder: '请输入', options: '选项一 / 选项二' } } }
function openReportCreate() { editingReport.value = null; reportForm.value = { reportCode: '', reportName: '', sourceTable: dataSources.value.find(item => item.enabled)?.source_code || 'work_order', chartType: 'TABLE', configJson: '{\n  "dimension": "status",\n  "metric": "count(*)"\n}' }; showReportModal.value = true }; function openReportEdit(row) { editingReport.value = row; reportForm.value = { reportCode: row.report_code, reportName: row.report_name, sourceTable: row.source_table, chartType: row.chart_type, configJson: row.config_json || '{}' }; showReportModal.value = true }
function openSourceCreate() { editingSource.value = null; sourceForm.value = { sourceCode: '', sourceName: '', sourceType: 'TABLE', configJson: '{}', schemaJson: '{\n  "columns": []\n}', status: 1 }; showSourceModal.value = true }; function openSourceEdit(row) { editingSource.value = row; sourceForm.value = { sourceCode: row.source_code, sourceName: row.source_name, sourceType: row.source_type, configJson: row.config_json || row.configJson || '{}', schemaJson: row.schema_json || row.schemaJson || '{}', status: row.enabled ? 1 : 0 }; showSourceModal.value = true }
function openPageCreate() { editingPage.value = null; pageForm.value = { pageCode: '', pageName: '', pageType: 'FORM', submitApi: '' }; pageSchema.value = { layout: 2, components: [], submitApi: '' }; selectedPageId.value = null; showPageModal.value = true }; function selectPage(page) { selectedPageId.value = page.id; editingPage.value = page; pageForm.value = { pageCode: page.page_code, pageName: page.page_name, pageType: page.page_type, submitApi: parseJson(page.schema_json, {}).submitApi || '' }; const schema = parseJson(page.schema_json, {}); pageSchema.value = { layout: Number(schema.layout || 2), components: schema.components || (schema.fields || []).map(field => ({ id: `${field.name}-${Math.random()}`, type: field.type === 'text' ? 'input' : field.type, props: { ...field, label: field.label || field.name } })), submitApi: schema.submitApi || '' }; selectedComponentId.value = pageSchema.value.components[0]?.id || null }
function addComponent(component) { pageSchema.value.components.push(defaultComponent(component)); selectedComponentId.value = pageSchema.value.components.at(-1).id }; function dragComponent(component) { dragState.value = { type: 'new', component } }; function dragExisting(index) { dragState.value = { type: 'existing', index } }; function dropComponent() { if (dragState.value?.type === 'new') addComponent(dragState.value.component); dragState.value = null }; function dropExisting(index) { if (dragState.value?.type !== 'existing') return; const [item] = pageSchema.value.components.splice(dragState.value.index, 1); pageSchema.value.components.splice(index, 0, item); dragState.value = null }; function removeComponent(index) { const removed = pageSchema.value.components.splice(index, 1)[0]; if (selectedComponentId.value === removed?.id) selectedComponentId.value = pageSchema.value.components[0]?.id || null }
function openDashboardCreate() { editingDashboard.value = null; dashboardForm.value = { dashboardCode: '', dashboardName: '', theme: 'dark-blue' }; dashboardSchema.value = { columns: 3, widgets: [] }; selectedWidgetId.value = null; showDashboardModal.value = true }; function selectDashboard(dashboard) { selectedDashboardId.value = dashboard.id; editingDashboard.value = dashboard; dashboardForm.value = { dashboardCode: dashboard.dashboard_code, dashboardName: dashboard.dashboard_name, theme: dashboard.theme || 'dark-blue' }; const layout = parseJson(dashboard.layout_json, {}); dashboardSchema.value = { columns: Number(layout.columns || 3), widgets: layout.widgets || [] }; selectedWidgetId.value = dashboardSchema.value.widgets[0]?.id || null }; function defaultWidget(widget) { return { id: `${widget.type}-${Date.now()}-${Math.random().toString(16).slice(2)}`, type: widget.type, title: widget.label, value: widget.type === 'kpi' ? '1,280' : '', subtitle: widget.type === 'kpi' ? '当前累计完成' : '', dataSource: dataSources.value.find(item => item.enabled)?.source_code || 'work_order', refreshSeconds: 30 } }; function addScreenWidget(widget) { const item = defaultWidget(widget); dashboardSchema.value.widgets.push(item); selectedWidgetId.value = item.id }; function dragScreenWidget(widget) { dragWidgetState.value = { type: 'new', widget } }; function dragExistingWidget(index) { dragWidgetState.value = { type: 'existing', index } }; function dropScreenWidget() { if (dragWidgetState.value?.type === 'new') addScreenWidget(dragWidgetState.value.widget); dragWidgetState.value = null }; function dropExistingWidget(index) { if (dragWidgetState.value?.type !== 'existing') return; const [item] = dashboardSchema.value.widgets.splice(dragWidgetState.value.index, 1); dashboardSchema.value.widgets.splice(index, 0, item); dragWidgetState.value = null }; function removeScreenWidget(index) { const removed = dashboardSchema.value.widgets.splice(index, 1)[0]; if (selectedWidgetId.value === removed?.id) selectedWidgetId.value = dashboardSchema.value.widgets[0]?.id || null }
async function load() { loading.value = true; try { const [reportData, sourceData, pageData, dashboardData, overviewData] = await Promise.all([request('/design/reports'), request('/design/data-sources'), request('/design/low-code/pages'), request('/design/dashboards'), request('/dashboard/overview')]); reports.value = reportData || []; dataSources.value = sourceData || []; lowCodePages.value = pageData || []; dashboards.value = dashboardData || []; dashboardOverview.value = overviewData || {}; if (tab.value === 'low-code' && lowCodePages.value.length && !selectedPageId.value) selectPage(lowCodePages.value[0]); if (tab.value === 'big-screen' && dashboards.value.length && !selectedDashboardId.value) selectDashboard(dashboards.value[0]) } catch (error) { showNotice(error.message, 'error') } finally { loading.value = false } }
async function saveReport() { if (!reportForm.value.reportCode || !reportForm.value.reportName) return showNotice('请完整填写报表编码和名称', 'warning'); try { JSON.parse(reportForm.value.configJson || '{}') } catch { return showNotice('配置 JSON 格式不正确', 'warning') } await saveRequest(editingReport.value ? `/design/reports/${editingReport.value.id}` : '/design/reports', editingReport.value ? 'PUT' : 'POST', reportForm.value, '报表已保存', showReportModal, load) }; async function publishReport(row) { await saveRequest(`/design/reports/${row.id}/publish`, 'POST', null, '报表已发布', null, load) }; async function previewReport(row) { try { previewData.value = await request(`/design/reports/${row.id}/preview`); showPreviewModal.value = true } catch (error) { showNotice(error.message, 'error') } }
async function saveSource() { if (!sourceForm.value.sourceCode || !sourceForm.value.sourceName) return showNotice('请填写数据源编码和名称', 'warning'); try { JSON.parse(sourceForm.value.configJson || '{}'); JSON.parse(sourceForm.value.schemaJson || '{}') } catch { return showNotice('数据源 JSON 格式不正确', 'warning') } await saveRequest(editingSource.value ? `/design/data-sources/${editingSource.value.id}` : '/design/data-sources', editingSource.value ? 'PUT' : 'POST', sourceForm.value, '数据源已保存', showSourceModal, load) }; async function toggleSource(row) { await saveRequest(`/design/data-sources/${row.id}/toggle`, 'POST', { enabled: !row.enabled }, row.enabled ? '数据源已停用' : '数据源已启用', null, load) }
async function savePage() { if (!pageForm.value.pageCode || !pageForm.value.pageName) return showNotice('请填写页面编码和名称', 'warning'); const payload = { ...pageForm.value, schemaJson: JSON.stringify({ layout: Number(pageSchema.value.layout || 2), components: pageComponents.value, submitApi: pageForm.value.submitApi }) }; const editingId = editingPage.value?.id; const pageCode = pageForm.value.pageCode; await saveRequest(editingId ? `/design/low-code/pages/${editingId}` : '/design/low-code/pages', editingId ? 'PUT' : 'POST', payload, '页面已保存', showPageModal, async () => { await load(); const item = lowCodePages.value.find(row => row.id === editingId) || lowCodePages.value.find(row => row.page_code === pageCode) || lowCodePages.value[0]; if (item) selectPage(item) }) }; async function publishPage() { if (!selectedPage.value) return; await savePage(); await saveRequest(`/design/low-code/pages/${selectedPage.value.id}/publish`, 'POST', null, '页面已发布', null, load) }
async function saveDashboard() { if (!dashboardForm.value.dashboardCode || !dashboardForm.value.dashboardName) return showNotice('请填写大屏编码和名称', 'warning'); const payload = { ...dashboardForm.value, layoutJson: JSON.stringify({ columns: Number(dashboardSchema.value.columns || 3), widgets: screenWidgets.value }) }; const wasEditing = Boolean(editingDashboard.value); const editingId = editingDashboard.value?.id; const dashboardCode = dashboardForm.value.dashboardCode; await saveRequest(wasEditing ? `/design/dashboards/${editingId}` : '/design/dashboards', wasEditing ? 'PUT' : 'POST', payload, '大屏配置已保存', showDashboardModal, async () => { await load(); const item = dashboards.value.find(row => row.id === editingId) || dashboards.value.find(row => row.dashboard_code === dashboardCode) || dashboards.value[0]; if (item) selectDashboard(item) }) }; async function publishDashboard() { if (!selectedDashboard.value) return; await saveDashboard(); await saveRequest(`/design/dashboards/${selectedDashboard.value.id}/publish`, 'POST', null, '大屏已发布', null, load) }
async function saveRequest(path, method, body, message, modal, after) { saving.value = true; try { await request(path, { method, ...(body === null ? {} : { body: JSON.stringify(body) }) }); if (modal) modal.value = false; showNotice(message); if (after) await after() } catch (error) { showNotice(error.message, 'error') } finally { saving.value = false } }
onMounted(load)
</script>
